"""FUNDED_SIM.json -> FUNDED_SIM.md. python funded_table.py"""
import json
from pathlib import Path

R = Path(__file__).resolve().parent
d = json.loads((R / 'FUNDED_SIM.json').read_text(encoding='utf-8'))['results']
usd = lambda v: '-' if v is None else f'${v:,.0f}'  # noqa: E731
pct = lambda v: '-' if v is None else f'{100 * v:.0f}%'  # noqa: E731
num = lambda v: '-' if v is None else f'{v:g}'  # noqa: E731
md = ['# funded_v1 on the Leveraged $50k reward account (generated by funded_table.py)', '',
      'Python/numba replay of the 8 EAs\' frozen native ledgers (2021-10 → 2026-10), funded_v1 guard defaults, firm rules as answered by Leveraged on 2026-10-27.',
      'In-sample replay, NOT a forecast and NOT a native combined run. Payout = 80% trader share; per week = total paid ÷ horizon (accounts that stop earn 0 after).',
      'MC = 1,000 resampled paths (4-week blocks). Breach = every open position at its stop. Cushion = $3,000 kept above $50,000 after each payout (assumption).', '',
      '## Expected payout per week', '',
      '| Nasdaq DI | Risk / trade | Payout / week 3y MC: mean (median) | Realistic range p10 – p90 | Payout / month | First-year MC / week | History 1y / week | Avg payout | Payouts in 3y | No payout in 3y | First payout (median day) |',
      '|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for v in d.values():
    m, a, h = v['mc3'], v['mc1'], v['hist1']
    md.append(f"| {v['portfolio']} | {v['risk']:g}% | **{usd(m['payout_week_mean'])}** ({usd(m['payout_week_median'])}) | {usd(m['payout_week_p10'])} – {usd(m['payout_week_p90'])} | "
              f"{usd(m['payout_month_mean'])} | {usd(a['payout_week_mean'])} | {usd(h['payout_week_mean'])} | {usd(m['total_paid_mean'] / max(m['payouts_mean'], 1e-9))} | {m['payouts_mean']} | "
              f"{pct(m['no_payout'])} | {num(m['first_payout_day_median'])} |")
md += ['', '## Risk data (3-year MC unless marked)', '',
       '| Nasdaq DI | Risk | Breach | Avg days to breach | Frozen | Floor locked at $50k (share / median day) | Worst day MC / history | Worst week MC | Max closed DD median / worst | Worst stop-marked DD | Winning days | Win / loss streak avg (max) | Trades / month | / day |',
       '|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for v in d.values():
    m, h = v['mc3'], v['hist1']
    md.append(f"| {v['portfolio']} | {v['risk']:g}% | {pct(m['breach'])} | {num(m['breach_days_mean'])} | {pct(m['freeze'])} | {pct(m['locked_share'])} / {num(m['lock_day_median'])} | "
              f"{usd(m['worst_day'])} / {usd(h['worst_day'])} | {usd(m['worst_week'])} | {usd(m['dd_closed_median'])} / {usd(m['dd_closed_worst'])} | {usd(m['dd_stop_worst'])} | "
              f"{pct(m['winning_days_share'])} | {m['win_streak_avg']} / {m['loss_streak_avg']} ({num(m['win_streak_max'])} / {num(m['loss_streak_max'])}) | {m['trades_per_month']} | {m['trades_per_day']} |")
md += ['', '## What to realistically expect: payout per week by scenario (1-year MC unless marked)', '',
       '| Nasdaq DI | Risk | Weak market (2021-23 blocks) | Middle (2023-24) | Strong (2024-26) | All history | Costs +0.10R per trade (3y) | Cushion $1,500 instead of $3,000 (3y) |',
       '|---|---:|---:|---:|---:|---:|---:|---:|']
for v in d.values():
    md.append(f"| {v['portfolio']} | {v['risk']:g}% | {usd(v['dev_1y']['payout_week_mean'])} | {usd(v['val_1y']['payout_week_mean'])} | {usd(v['oos_1y']['payout_week_mean'])} | "
              f"{usd(v['mc1']['payout_week_mean'])} | {usd(v['mc3_cost010']['payout_week_mean'])} | {usd(v['mc3_cushion1500']['payout_week_mean'])} |")
(R / 'FUNDED_SIM.md').write_text('\n'.join(md) + '\n', encoding='utf-8'); print('\n'.join(md))
